/**
 * Field-by-field diff of two resource configs (the .json format), for the admin's confirm step and
 * "View diff" in History. Text fields come per language (EN and ES side by side) with word-level
 * segments, so the admin can highlight exactly what changed. Pure data: the admin renders it with
 * textContent (never as HTML).
 *
 *   diff(before, after) -> {
 *     changed: n,                                         number of fields that differ
 *     shared:  [{ field, label, before, after }],          subject, levels, courseTags, ... (as text)
 *     text:    [{ field, label, en: side | null, es: side | null }]   side = { before, after, segments }
 *     slugChanges: [{ lang, from, to }],                   -> "the old URL will 301 to the new one"
 *   }
 * segments: [{ op: "=" | "-" | "+", text }]
 */
"use strict";

const SHARED = [
  ["file", "Tool file"], ["subject", "Subject"], ["levels", "Levels"], ["courseTags", "Course tags"],
  ["relatedExamPage", "Related exam page"], ["related", "Related resources"], ["files", "PDF files (order and labels)"],
];
const TEXT = [
  ["title", "Title"], ["slug", "Slug"], ["description", "Description"], ["intro", "Intro"],
  ["howTo", "How to use it"], ["keyIdeas", "Key ideas"], ["faq", "FAQ"], ["keywords", "Keywords"],
];

/** A field's value as display text: lists one item per line, FAQ as Q/A blocks, PDFs as name: EN / ES. */
function asText(field, v) {
  if (v === undefined || v === null) return "";
  if (field === "faq") return (v || []).map((f, i) => `${i + 1}. Q: ${f.q}\n   A: ${f.a}`).join("\n");
  if (field === "files") return (v || []).map((f) => `${f.file}: ${f.en} / ${f.es}`).join("\n");
  if (Array.isArray(v)) return v.join(field === "levels" || field === "courseTags" || field === "keywords" ? ", " : "\n");
  return String(v);
}

const tokens = (s) => String(s).split(/(\s+)/).filter((t) => t !== "");

/** Word-level diff (LCS); falls back to "all removed, all added" for very long texts. */
function segments(a, b) {
  if (a === b) return a ? [{ op: "=", text: a }] : [];
  const x = tokens(a), y = tokens(b);
  const out = [];
  const push = (op, text) => { const last = out[out.length - 1]; if (last && last.op === op) last.text += text; else out.push({ op, text }); };
  if (x.length * y.length > 4e6) { if (a) push("-", a); if (b) push("+", b); return out; }
  const n = x.length, m = y.length;
  const L = Array.from({ length: n + 1 }, () => new Uint32Array(m + 1));
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) L[i][j] = x[i] === y[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1]);
  let i = 0, j = 0;
  while (i < n && j < m) {
    if (x[i] === y[j]) { push("=", x[i]); i++; j++; }
    else if (L[i + 1][j] >= L[i][j + 1]) push("-", x[i++]);
    else push("+", y[j++]);
  }
  while (i < n) push("-", x[i++]);
  while (j < m) push("+", y[j++]);
  return out;
}

function diff(before, after) {
  const b = before || {}, a = after || {};
  const out = { changed: 0, shared: [], text: [], slugChanges: [] };
  for (const [field, label] of SHARED) {
    const x = asText(field, b[field]), y = asText(field, a[field]);
    if (x !== y) { out.shared.push({ field, label, before: x, after: y }); out.changed++; }
  }
  for (const [field, label] of TEXT) {
    const row = { field, label, en: null, es: null };
    for (const lang of ["en", "es"]) {
      const x = asText(field, (b[lang] || {})[field]), y = asText(field, (a[lang] || {})[field]);
      if (x !== y) { row[lang] = { before: x, after: y, segments: segments(x, y) }; out.changed++; }
    }
    if (row.en || row.es) out.text.push(row);
  }
  for (const lang of ["en", "es"]) {
    const from = (b[lang] || {}).slug, to = (a[lang] || {}).slug;
    if (from && to && from !== to) out.slugChanges.push({ lang, from, to });
  }
  return out;
}

module.exports = { diff, segments, asText };
